// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *BehaviourWhereInput) AddPredicates(predicates ...predicate.Behaviour) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the BehaviourWhereInput filter on the BehaviourQuery builder.
func (i *BehaviourWhereInput) Filter(q *BehaviourQuery) (*BehaviourQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyBehaviourWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

// ErrEmptyBehaviourWhereInput is returned in case the BehaviourWhereInput is empty.
var ErrEmptyBehaviourWhereInput = errors.New("ent: empty predicate BehaviourWhereInput")

