// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *BenchEvalWhereInput) AddPredicates(predicates ...predicate.BenchEval) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the BenchEvalWhereInput filter on the BenchEvalQuery builder.
func (i *BenchEvalWhereInput) Filter(q *BenchEvalQuery) (*BenchEvalQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyBenchEvalWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

