// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *BenchRunWhereInput) AddPredicates(predicates ...predicate.BenchRun) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the BenchRunWhereInput filter on the BenchRunQuery builder.
func (i *BenchRunWhereInput) Filter(q *BenchRunQuery) (*BenchRunQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyBenchRunWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

// ErrEmptyBenchRunWhereInput is returned in case the BenchRunWhereInput is empty.
var ErrEmptyBenchRunWhereInput = errors.New("ent: empty predicate BenchRunWhereInput")

