// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *CodeFileWhereInput) AddPredicates(predicates ...predicate.CodeFile) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the CodeFileWhereInput filter on the CodeFileQuery builder.
func (i *CodeFileWhereInput) Filter(q *CodeFileQuery) (*CodeFileQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyCodeFileWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

