// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *DBConfigWhereInput) AddPredicates(predicates ...predicate.DBConfig) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the DBConfigWhereInput filter on the DBConfigQuery builder.
func (i *DBConfigWhereInput) Filter(q *DBConfigQuery) (*DBConfigQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyDBConfigWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

