// Filter applies the ExternalSourceWhereInput filter on the ExternalSourceQuery builder.
func (i *ExternalSourceWhereInput) Filter(q *ExternalSourceQuery) (*ExternalSourceQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyExternalSourceWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

