// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *HandoffWhereInput) AddPredicates(predicates ...predicate.Handoff) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the HandoffWhereInput filter on the HandoffQuery builder.
func (i *HandoffWhereInput) Filter(q *HandoffQuery) (*HandoffQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyHandoffWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

