// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *HotfixWhereInput) AddPredicates(predicates ...predicate.Hotfix) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the HotfixWhereInput filter on the HotfixQuery builder.
func (i *HotfixWhereInput) Filter(q *HotfixQuery) (*HotfixQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyHotfixWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

