// Filter applies the LearnRunWhereInput filter on the LearnRunQuery builder.
func (i *LearnRunWhereInput) Filter(q *LearnRunQuery) (*LearnRunQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyLearnRunWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

