// Filter applies the MissionWhereInput filter on the MissionQuery builder.
func (i *MissionWhereInput) Filter(q *MissionQuery) (*MissionQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyMissionWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

