// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *PatternWhereInput) AddPredicates(predicates ...predicate.Pattern) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the PatternWhereInput filter on the PatternQuery builder.
func (i *PatternWhereInput) Filter(q *PatternQuery) (*PatternQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyPatternWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

// ErrEmptyPatternWhereInput is returned in case the PatternWhereInput is empty.
var ErrEmptyPatternWhereInput = errors.New("ent: empty predicate PatternWhereInput")

// P returns a predicate for filtering patterns.
// An error is returned if the input is empty or invalid.
