// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *PiiPatternWhereInput) AddPredicates(predicates ...predicate.PiiPattern) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the PiiPatternWhereInput filter on the PiiPatternQuery builder.
func (i *PiiPatternWhereInput) Filter(q *PiiPatternQuery) (*PiiPatternQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyPiiPatternWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

