// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *PlaybookWhereInput) AddPredicates(predicates ...predicate.Playbook) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the PlaybookWhereInput filter on the PlaybookQuery builder.
func (i *PlaybookWhereInput) Filter(q *PlaybookQuery) (*PlaybookQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyPlaybookWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

