// Filter applies the QueryLogWhereInput filter on the QueryLogQuery builder.
func (i *QueryLogWhereInput) Filter(q *QueryLogQuery) (*QueryLogQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyQueryLogWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

