// Filter applies the ReminderWhereInput filter on the ReminderQuery builder.
func (i *ReminderWhereInput) Filter(q *ReminderQuery) (*ReminderQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyReminderWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

