// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *RunWhereInput) AddPredicates(predicates ...predicate.Run) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the RunWhereInput filter on the RunQuery builder.
func (i *RunWhereInput) Filter(q *RunQuery) (*RunQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyRunWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

