// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *SuggestionWhereInput) AddPredicates(predicates ...predicate.Suggestion) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the SuggestionWhereInput filter on the SuggestionQuery builder.
func (i *SuggestionWhereInput) Filter(q *SuggestionQuery) (*SuggestionQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptySuggestionWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

